/**
 * 결과 출력용 인셋 박스 — 기존 .inset-box 대체
 */
export default function ResultBox({ title, children, accent = false }) {
  return (
    <div
      style={{
        background: 'var(--bg-inset)',
        border: `1px solid ${accent ? 'var(--bd-accent)' : 'var(--bd-subtle)'}`,
        borderRadius: 8,
        padding: 14,
        marginTop: 16,
        transition: 'background 0.25s',
      }}
    >
      {title && (
        <h5
          style={{
            fontSize: 12,
            fontWeight: 700,
            color: 'var(--ac-main)',
            marginBottom: 8,
            letterSpacing: '0.04em',
            textTransform: 'uppercase',
          }}
        >
          {title}
        </h5>
      )}
      {children}
    </div>
  )
}
